    public <E> E persist(E entity) {
        em.persist(entity);
        em.flush();
        return entity;
    }

    /** Flushes pending changes and clears the persistence context so subsequent reads hit the database. */
    public void flushAndClear() {
        em.flush();
        em.clear();
    }
